dualStart:
static _Bool dualStart(_Bool holdCurrent)
{
 if (voicePromptsIsPlaying())
 {
  voicePromptsTerminate();
 }
 directChannelNumber = 0;
 uiDataGlobal.talkaround = 0;
 uiDataGlobal.Scan.active = 1;
 uiDataGlobal.Scan.scanType = SCAN_TYPE_DUAL_CHANNEL;
 uiDataGlobal.Scan.lastIteration = 0;
 uiDataGlobal.Scan.direction = 1;
 uiDataGlobal.Scan.stepTimeMilliseconds = settingsGetScanStepTimeMilliseconds();
 uiDataGlobal.Scan.state = SCAN_STATE_SCANNING;
 scanNextChannelReady = 0;
 if (holdCurrent)
 {
  dualSetDwell();
  uiDataGlobal.Scan.timer.timeout = (nonVolatileSettings.scanDelay * 1000);
  uiDataGlobal.Scan.state = SCAN_STATE_PAUSED;
 }
 else
 {
  if (dcIsOnB())
  {
   dualTune(0);
  }
  dualSetDwell();
 }
 uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
 uiChannelModeUpdateScreen(0);
 return 1;
}

dualLeaveOnB:
static void dualLeaveOnB(void)
{
 uint16_t b = dcChannelB();
 int pos = -1;
 _Bool wasAll = ((currentZone).NOT_IN_CODEPLUGDATA_indexNumber < 0);
 dcSetOnB(0);
 lastHeardClearLastID();
 if (wasAll == 0)
 {
  pos = dcFindPos(currentZone.NOT_IN_CODEPLUGDATA_numChannelsInZone, b, dualZoneChannelAt, ((void *)0));
 }
 if (wasAll || (pos >= 0))
 {
  codeplugSetLastUsedChannelInZone(currentZone.NOT_IN_CODEPLUGDATA_indexNumber, (int16_t)(wasAll ? b : pos));
 }
 else
 {
  _Generic((nonVolatileSettings.currentZone), _Bool: settingsSetBOOL, int8_t: settingsSetINT8, uint8_t: settingsSetUINT8, int16_t: settingsSetINT16, uint16_t: settingsSetUINT16, int32_t: settingsSetINT32, uint32_t: settingsSetUINT32 )(&nonVolatileSettings.currentZone, (int16_t)(codeplugZonesGetCount() - 1));
  uiChannelInitializeCurrentZone();
  codeplugSetLastUsedChannelInZone(currentZone.NOT_IN_CODEPLUGDATA_indexNumber, (int16_t)b);
  uiNotificationShow(NOTIFICATION_TYPE_MESSAGE, NOTIFICATION_ID_CARD, (2000U), (currentLanguage->dual_zone_all), (1));
 }
 uiChannelModeLoadChannelData(0, 0);
}

dualDisable:
static void dualDisable(void)
{
 _Bool stayB = dualSelectedIsB();
 uint8_t retType = dcTypeA();
 uint16_t retIdx = (dcAIsVfo() ? 0U : dualChannelA());
 if (stayB)
 {
  uiDataGlobal.Scan.active = 0;
  uiDataGlobal.Scan.scanType = SCAN_TYPE_NORMAL_STEP;
  uiDataGlobal.Scan.state = SCAN_STATE_SCANNING;
  scanNextChannelReady = 0;
  if (dcBIsVfo())
  {
   dcSetTxHold(0);
   (void)dcDisableWithReturnA(retType, retIdx);
   dualLeaveOnVfo(dualVfoIdx());
  }
  else
  {
   dcSetTxHold(0);
   (void)dcDisableWithReturnA(retType, retIdx);
   dualLeaveOnB();
  }
  uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
  return;
 }
 else if (dualIsRunning())
 {
  dualSuspend();
 }
 else if (dcIsOnB())
 {
  dualTune(0);
 }
 dcSetTxHold(0);
 (void)dcSetEnabled(0, 1);
 uiDataGlobal.displayQSOState = QSO_DISPLAY_DEFAULT_SCREEN;
 if (dcAIsVfo())
 {
  if (dcBIsVfo() == 0)
  {
   channelScreenChannelData.rxFreq = 0U;
  }
  dualLeaveOnVfo(dualCardVfo(0));
 }
}

dualApplyReturnA:
static _Bool dualApplyReturnA(uint8_t rt, uint16_t ri)
{
 int pos = -1;
 if (dcSameTarget(rt, ri, dcTypeB(), dcChannelB()))
 {
  return 0;
 }
 if (rt == 0U)
 {
  if (codeplugAllChannelsIndexIsInUse(ri) == 0)
  {
   return 0;
  }
  _Bool allCh = ((currentZone).NOT_IN_CODEPLUGDATA_indexNumber < 0);
  pos = (allCh ? (int)ri : dcFindPos(currentZone.NOT_IN_CODEPLUGDATA_numChannelsInZone, ri, dualZoneChannelAt, ((void *)0)));
  if (pos < 0)
  {
   return 0;
  }
 }
 _Bool bufHadB = (currentChannelData == &channelScreenChannelData);
 dcSetOnB(1);
 dcSetPointerB(1);
 dcSetTypeA(rt);
 if (rt == 0U)
 {
  codeplugSetLastUsedChannelInZone(currentZone.NOT_IN_CODEPLUGDATA_indexNumber, (int16_t)pos);
  codeplugChannelGetDataForIndex(ri, (bufHadB ? &scanNextChannelData : &channelScreenChannelData));
 }
 return 1;
}

dualMeterRow:
