}

dualRow4Text:
static void dualRow4Text(char *l4, size_t size, const CodeplugChannel_t *rec, _Bool callerHere, uint16_t *bearing, _Bool *bearingKnown)
{
 uint8_t lvl = ((rec->libreDMR_Power != 0x00) ? (uint8_t)(rec->libreDMR_Power - 1U) : nonVolatileSettings.txPowerLevel);
 *bearing = 0U;
 *bearingKnown = 0;
 snprintf(l4, size, "%s %s%s", ((rec->chMode == RADIO_MODE_DIGITAL) ? "DMR" : "FM"), uiSafeStr(getPowerLevel(lvl)), uiSafeStr(getPowerLevelUnit(lvl)));
 char label[16];
 size_t n = strlen(l4);
 _Bool known = 0;
 if (callerHere && (LinkHead != ((void *)0)) && (LinkHead->locationLat <= 90) && settingsLocationIsValid() &&
   lcDistLabel(label, sizeof(label), 1, settingsLocationGetLatitude(), settingsLocationGetLongitude(), LinkHead->locationLat, LinkHead->locationLon, bearing, &known) &&
   ((n + 1U + strlen(label) + (known ? 2U : 0U)) <= 24))
 {
  snprintf((l4 + n), (size - n), " %s", label);
  *bearingKnown = known;
 }
}

dualRenderRow:
static void dualRenderRow(int16_t y, _Bool isB, uint16_t ch, uint8_t vfoType, _Bool selected, _Bool active, _Bool callerHere)
{
 CodeplugChannel_t tmp;
 const CodeplugChannel_t *rec = &tmp;
 char name[17];
 char l1[23 + 1];
 char l2[17];
 char l3[23 + 1];
 char l4[24 + 1];
 char letter[2];
 uint16_t bearing = 0U;
 _Bool bearingKnown = 0;
 _Bool isVfo = (vfoType != 0U);
 _Bool known = (isVfo || ((ch >= 1U) && (ch <= 1024U) && codeplugAllChannelsIndexIsInUse(ch)));
 name[0] = 0;
 l1[0] = 0;
 l2[0] = 0;
 l3[0] = 0;
 l4[0] = 0;
 if (known)
 {
  if (isVfo)
  {
   rec = &settingsVFOChannel[(vfoType == 2U) ? 1 : 0];
  }
  else
  {
   codeplugChannelGetDataForIndex(ch, &tmp);
   codeplugUtilConvertBufToDisplayString(tmp.name, name, 16);
   rec = dualCardMem(isB, &tmp);
  }
  if (rec->chMode == RADIO_MODE_DIGITAL)
  {
   _Bool numOnly;
   uint8_t tsFlags;
   uint32_t dest = dualDestination(rec, l2, &numOnly, &tsFlags, dualCardTgIdx(isB, vfoType));
   size_t n;
   snprintf(l3, sizeof(l3), "TS%d CC%d", (int)dualEffectiveTs(rec, tsFlags), (int)rec->txColor);
   n = strlen(l3);
   if (callerHere && (LinkHead != ((void *)0)))
   {
    snprintf((l3 + n), (sizeof(l3) - n), " %.11s", LinkHead->talkgroup);
   }
   else if (numOnly == 0)
   {
    char num[12];
    snprintf(num, sizeof(num), "%s%u", (((dest >> 24) != 0x00) ? currentLanguage->pc : currentLanguage->tg), (unsigned)(dest & 0x00FFFFFFU));
    if ((n + 1U + strlen(num)) <= 23)
    {
     snprintf((l3 + n), (sizeof(l3) - n), " %s", num);
    }
   }
  }
  else
  {
   int mhz = (int)(rec->rxFreq / 100000U);
   snprintf(l2, sizeof(l2), "FM %d.%05d", mhz, (int)(rec->rxFreq - ((uint32_t)mhz * 100000U)));
   dualFmToneLine(l3, sizeof(l3), rec->rxTone, rec->txTone, (codeplugChannelGetFlag((CodeplugChannel_t *)rec, CHANNEL_FLAG_BW_25K) != 0));
  }
  dualRow4Text(l4, sizeof(l4), rec, callerHere, &bearing, &bearingKnown);
 }
 if (callerHere)
 {
  dualCallerText(l2);
 }
 if ((directChannelNumber != 0) && (isB == dcPointerB()))
 {
  dualEntryText(l2, sizeof(l2));
 }
 displayThemeApply(THEME_ITEM_FG_DECORATION, THEME_ITEM_BG);
 displayDrawRect(1, y, 158, 57, 1);
 letter[0] = (isB ? 'B' : 'A');
 letter[1] = 0;
 displayThemeApply(THEME_ITEM_FG_CHANNEL_NAME, THEME_ITEM_BG);
 if (selected)
 {
  displayFillRect(3, (y + 2), 10, 18, 0);
 }
 else
 {
  displayDrawRect(3, (y + 2), 10, 18, 1);
 }
 displayPrintCore(4, (y + 3), letter, FONT_SIZE_3, TEXT_ALIGN_LEFT, selected);
 if (isVfo)
 {
  if (rec->chMode == RADIO_MODE_DIGITAL)
  {
   int mhz = (int)(rec->rxFreq / 100000U);
   snprintf(l1, sizeof(l1), "VFO %c %d.%05d", ((vfoType == 2U) ? 'B' : 'A'), mhz, (int)(rec->rxFreq - ((uint32_t)mhz * 100000U)));
  }
  else
  {
   snprintf(l1, sizeof(l1), "VFO %c", ((vfoType == 2U) ? 'B' : 'A'));
  }
 }
 else if (ch >= 1U)
 {
  snprintf(l1, sizeof(l1), ((name[0] != 0) ? "%u %s" : "%u"), (unsigned)ch, name);
 }
 unsigned un = uiUnreadCountCard(isB);
 unsigned aprsUn = (isB ? uiUnreadCount('A') : 0U);
 int16_t res = (int16_t)(((un > 0U) ? 23 : 0) + ((aprsUn > 0U) ? 16 : 0));
 size_t l1max = (size_t)((156 + 1 - 15 - res) / 6);
 if (strlen(l1) > l1max)
 {
  l1[l1max] = 0;
 }
 displayPrintCore(15, (y + 2), l1, FONT_SIZE_1, TEXT_ALIGN_LEFT, 0);
 if (un > 0U)
 {
  char num[2];
  num[0] = ((un > 9U) ? '+' : (char)('0' + un));
  num[1] = 0;
  displayThemeApply(THEME_ITEM_FG_CHANNEL_NAME, THEME_ITEM_BG);
  displayPrintCore(135, (y + 2), "D", FONT_SIZE_1, TEXT_ALIGN_LEFT, 0);
  displayDrawRect(142, (y + 2 + 1), 8, 6, 1);
  displayDrawLine(142, (y + 2 + 1), (142 + 4), (y + 2 + 4), 1);
  displayDrawLine((142 + 7), (y + 2 + 1), (142 + 4), (y + 2 + 4), 1);
  displayPrintCore(151, (y + 2), num, FONT_SIZE_1, TEXT_ALIGN_LEFT, 0);
 }
 if (aprsUn > 0U)
 {
  char ap[3];
  int16_t ax = ((un > 0U) ? 119 : 143);
  ap[0] = 'A';
  ap[1] = ((aprsUn > 9U) ? '+' : (char)('0' + aprsUn));
  ap[2] = 0;
  displayThemeApply(THEME_ITEM_FG_CHANNEL_NAME, THEME_ITEM_BG);
  displayFillRect(ax, (y + 1), 14, 9, 0);
  displayPrintCore((ax + 1), (y + 1 + 1), ap, FONT_SIZE_1, TEXT_ALIGN_LEFT, 1);
 }
 displayThemeApply((callerHere ? THEME_ITEM_FG_CHANNEL_CONTACT_INFO : THEME_ITEM_FG_CHANNEL_CONTACT), THEME_ITEM_BG);
 displayPrintCore(15, (y + 11), l2, FONT_SIZE_3, TEXT_ALIGN_LEFT, 0);
 displayThemeApply(THEME_ITEM_FG_CHANNEL_NAME, THEME_ITEM_BG);
 displayPrintCore(3, (y + 28), l3, FONT_SIZE_1, TEXT_ALIGN_LEFT, 0);
 displayPrintCore(3, (y + 37), l4, FONT_SIZE_1, TEXT_ALIGN_LEFT, 0);
 if (bearingKnown)
 {
  lcDistArrow_t a;
  lcDistSpan_t tail = { .x0 = 3, .x1 = (int16_t)(3 + (strlen(l4) * 6)), .y = (int16_t)(y + 36), .h = 8 };
  lcDistSpan_t above = { .x0 = 0, .x1 = 0, .y = 0, .h = 0 };
  lcDistArrowAfter(&a, &tail, &above, (156 + 1), bearing);
  displayThemeApply(THEME_ITEM_FG_CHANNEL_CONTACT_INFO, THEME_ITEM_BG);
  displayFillTriangle(a.g.tx, a.g.ty, a.g.lx, a.g.ly, a.g.nx, a.g.ny, 1);
  displayFillTriangle(a.g.tx, a.g.ty, a.g.rx, a.g.ry, a.g.nx, a.g.ny, 1);
